<?php require '../config/app.php';require_role('patient');$title='Book a Test | DiagnosCare';$basePath='../';$uid=user()['id'];$tests=$pdo->query("SELECT * FROM diagnostic_tests ORDER BY category,name")->fetchAll();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$test=(int)$_POST['test_id'];$date=$_POST['appointment_date']??'';$time=$_POST['appointment_time']??'';$notes=trim($_POST['notes']??'');if($date<date('Y-m-d'))flash('danger','Please select today or a future date.');else{$st=$pdo->prepare("SELECT COUNT(*) FROM appointments WHERE appointment_date=? AND appointment_time=? AND status<>'Cancelled'");$st->execute([$date,$time]);if($st->fetchColumn()>0)flash('danger','That time slot is already booked.');else{$st=$pdo->prepare("SELECT price FROM diagnostic_tests WHERE id=?");$st->execute([$test]);$price=$st->fetchColumn();if($price===false)flash('danger','Please choose a valid test.');else{$st=$pdo->prepare("INSERT INTO appointments(patient_id,test_id,appointment_date,appointment_time,notes) VALUES(?,?,?,?,?)");$st->execute([$uid,$test,$date,$time,$notes]);$id=$pdo->lastInsertId();$st=$pdo->prepare("INSERT INTO payments(appointment_id,amount,method,transaction_id,status) VALUES(?,?,?,?,?)");$st->execute([$id,$price,'UPI','PENDING-'.$id.'-'.time(),'Pending']);flash('success','Appointment created. Complete payment next.');redirect("payment.php?id=$id");}}}}require '../partials/header.php';?>
<div class="row justify-content-center"><div class="col-xl-9"><div class="d-flex align-items-center gap-3 mb-4"><div class="feature-icon"><i class="bi bi-calendar2-plus"></i></div><div><h2 class="dashboard-title mb-1">Book your diagnostic test</h2><p class="text-muted mb-0">Select a service, date and convenient time.</p></div></div><div class="card p-4 p-md-5"><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="row g-4"><div class="col-12"><label class="form-label fw-semibold">Diagnostic test</label><select id="testSelect" name="test_id" class="form-select form-select-lg" required><option value="">Choose a test...</option><?php foreach($tests as $t):?><option value="<?=$t['id']?>" data-price="<?=$t['price']?>"><?=e($t['name'])?> — <?=money($t['price'])?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label fw-semibold">Date</label><input type="date" min="<?=date('Y-m-d')?>" name="appointment_date" class="form-control form-control-lg" required></div><div class="col-md-6"><label class="form-label fw-semibold">Time</label><select name="appointment_time" class="form-select form-select-lg" required><?php for($h=9;$h<=17;$h++):foreach([0,30] as $m):if($h==17&&$m==30)continue;$v=sprintf('%02d:%02d:00',$h,$m);?><option value="<?=$v?>"><?=date('h:i A',strtotime($v))?></option><?php endforeach;endfor;?></select></div><div class="col-12"><div id="priceBox" class="p-3 rounded-3 bg-light d-none"><div class="d-flex justify-content-between"><span>Estimated test fee</span><strong id="selectedPrice"></strong></div></div></div><div class="col-12"><label class="form-label fw-semibold">Notes <span class="text-muted fw-normal">(optional)</span></label><textarea name="notes" class="form-control" rows="3" placeholder="Any information for the lab..."></textarea></div><div class="col-12"><button class="btn btn-primary btn-lg"><i class="bi bi-calendar-check me-1"></i> Confirm Appointment</button> <a href="dashboard.php" class="btn btn-light btn-lg">Cancel</a></div></div></form></div></div></div><script>const s=document.getElementById('testSelect'),b=document.getElementById('priceBox'),p=document.getElementById('selectedPrice');s.addEventListener('change',()=>{let o=s.options[s.selectedIndex];if(o.value){p.textContent='₹'+Number(o.dataset.price).toLocaleString('en-IN',{minimumFractionDigits:2});b.classList.remove('d-none')}else b.classList.add('d-none')});</script><?php require '../partials/footer.php';?>
